class Solution {
public:
    string minCostGoodCaption(string caption) {
        int n = caption.size();
        if (n < 3) return "";
        const long long INF = LLONG_MAX / 4;
        vector<vector<long long>> pre(26, vector<long long>(n + 1, 0));
        for (int c = 0; c < 26; c++)
            for (int i = 0; i < n; i++) pre[c][i + 1] = pre[c][i] + abs(caption[i] - 'a' - c);
        vector<long long> bestF(n + 1, INF); bestF[n] = 0;
        vector<vector<long long>> suf(26, vector<long long>(n + 2, INF));
        vector<vector<int>> smi(26, vector<int>(n + 2, n));
        for (int c = 0; c < 26; c++)
            for (int j = n; j >= 0; j--) {
                long long v = pre[c][j] + bestF[j];
                if (j == n || v <= suf[c][j + 1]) { suf[c][j] = v; smi[c][j] = j; }
                else { suf[c][j] = suf[c][j + 1]; smi[c][j] = smi[c][j + 1]; }
            }
        for (int i = n - 3; i >= 0; i--) {
            long long b = INF;
            for (int c = 0; c < 26; c++) b = min(b, suf[c][i + 3] - pre[c][i]);
            bestF[i] = b;
        }
        if (bestF[0] >= INF) return "";
        string res; int i = 0; long long rem = bestF[0];
        while (i < n) {
            int c = 0;
            while (suf[c][i + 3] - pre[c][i] != rem) c++;
            int L = smi[c][i + 3] - i;
            res.append(L, char('a' + c));
            rem -= pre[c][i + L] - pre[c][i];
            i += L;
        }
        return res;
    }
};

