class Solution {
    public String minCostGoodCaption(String caption) {
        int n = caption.length();
        if (n < 3) return "";
        long INF = Long.MAX_VALUE / 4;
        long[][] pre = new long[26][n + 1];
        for (int c = 0; c < 26; c++)
            for (int i = 0; i < n; i++) pre[c][i + 1] = pre[c][i] + Math.abs(caption.charAt(i) - 'a' - c);
        long[] bestF = new long[n + 1]; Arrays.fill(bestF, INF); bestF[n] = 0;
        long[][] suf = new long[26][n + 2]; for (long[] r : suf) Arrays.fill(r, INF);
        int[][] smi = new int[26][n + 2]; for (int[] r : smi) Arrays.fill(r, n);
        for (int c = 0; c < 26; c++)
            for (int j = n; j >= 0; j--) {
                long v = pre[c][j] + bestF[j];
                if (j == n || v <= suf[c][j + 1]) { suf[c][j] = v; smi[c][j] = j; }
                else { suf[c][j] = suf[c][j + 1]; smi[c][j] = smi[c][j + 1]; }
            }
        for (int i = n - 3; i >= 0; i--) {
            long b = INF;
            for (int c = 0; c < 26; c++) b = Math.min(b, suf[c][i + 3] - pre[c][i]);
            bestF[i] = b;
        }
        if (bestF[0] >= INF) return "";
        StringBuilder sb = new StringBuilder();
        int i = 0; long rem = bestF[0];
        while (i < n) {
            int c = 0;
            while (suf[c][i + 3] - pre[c][i] != rem) c++;
            int L = smi[c][i + 3] - i;
            for (int k = 0; k < L; k++) sb.append((char) ('a' + c));
            rem -= pre[c][i + L] - pre[c][i];
            i += L;
        }
        return sb.toString();
    }
}

