var minCostGoodCaption = function(caption) {
    const n = caption.length;
    if (n < 3) return "";
    const INF = Infinity;
    const pre = Array.from({length: 26}, () => new Array(n + 1).fill(0));
    for (let c = 0; c < 26; c++)
        for (let i = 0; i < n; i++) pre[c][i + 1] = pre[c][i] + Math.abs(caption.charCodeAt(i) - 97 - c);
    const bestF = new Array(n + 1).fill(INF); bestF[n] = 0;
    const suf = Array.from({length: 26}, () => new Array(n + 2).fill(INF));
    const smi = Array.from({length: 26}, () => new Array(n + 2).fill(n));
    for (let c = 0; c < 26; c++)
        for (let j = n; j >= 0; j--) {
            const v = pre[c][j] + bestF[j];
            if (j === n || v <= suf[c][j + 1]) { suf[c][j] = v; smi[c][j] = j; }
            else { suf[c][j] = suf[c][j + 1]; smi[c][j] = smi[c][j + 1]; }
        }
    for (let i = n - 3; i >= 0; i--) {
        let b = INF;
        for (let c = 0; c < 26; c++) b = Math.min(b, suf[c][i + 3] - pre[c][i]);
        bestF[i] = b;
    }
    if (bestF[0] === INF) return "";
    let res = "", i = 0, rem = bestF[0];
    while (i < n) {
        let c = 0;
        while (suf[c][i + 3] - pre[c][i] !== rem) c++;
        const L = smi[c][i + 3] - i;
        res += String.fromCharCode(97 + c).repeat(L);
        rem -= pre[c][i + L] - pre[c][i];
        i += L;
    }
    return res;
};
